ALTER TABLE public.user_preferences ADD COLUMN IF NOT EXISTS browser_notifications boolean NOT NULL DEFAULT false;
ALTER TABLE public.user_preferences ADD COLUMN IF NOT EXISTS daily_digest boolean NOT NULL DEFAULT false;
ALTER TABLE public.user_preferences ADD COLUMN IF NOT EXISTS email_notifications boolean NOT NULL DEFAULT false;
ALTER TABLE public.user_preferences ADD COLUMN IF NOT EXISTS notify_min_score numeric NOT NULL DEFAULT 0.4 CHECK (notify_min_score BETWEEN 0 AND 1);
CREATE OR REPLACE FUNCTION public.sb_watchlist() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT jsonb_build_object('id',w.id,'name',w.name,'items',coalesce((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.name) FROM public.watchlist_items i JOIN public.companies c ON c.id=i.company_id WHERE i.watchlist_id=w.id AND NOT c.is_demo),'[]'::jsonb)) FROM public.watchlists w WHERE w.user_id=(SELECT auth.uid())::text AND w.name='관심종목' $$;
REVOKE ALL ON FUNCTION public.sb_watchlist() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sb_watchlist() TO authenticated;
CREATE OR REPLACE FUNCTION public.sb_notification_settings(p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u text:=(SELECT auth.uid())::text; r jsonb; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='PT401'; END IF; PERFORM public.sb_rate_limit(); IF p IS NULL OR jsonb_typeof(p)<>'object' OR octet_length(p::text)>2048 THEN RAISE EXCEPTION 'invalid_settings' USING ERRCODE='PT422'; END IF; UPDATE public.user_preferences SET browser_notifications=coalesce((p->>'browser_notifications')::boolean,browser_notifications),daily_digest=coalesce((p->>'daily_digest')::boolean,daily_digest),email_notifications=coalesce((p->>'email_notifications')::boolean,email_notifications),notify_min_score=coalesce((p->>'notify_min_score')::numeric,notify_min_score),updated_at=now() WHERE user_id=u RETURNING to_jsonb(user_preferences.*) INTO r; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.sb_notification_settings(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sb_notification_settings(jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION app_private.sb_event_visible(eid text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ WITH RECURSIVE ancestors(id) AS (SELECT eid UNION SELECT f.event_id FROM ancestors a JOIN public.changes c ON c.event_id=a.id JOIN public.facts f ON f.id=c.previous_fact_id) SELECT EXISTS(SELECT 1 FROM public.events e JOIN public.documents d ON d.id=e.document_id WHERE e.id=eid AND e.state IN ('published','superseded') AND e.published_to_users_at IS NOT NULL AND NOT d.is_demo) AND NOT EXISTS(SELECT 1 FROM ancestors a JOIN public.events e ON e.id=a.id JOIN public.documents d ON d.id=e.document_id WHERE e.state NOT IN ('published','superseded') OR d.is_demo OR NOT EXISTS(SELECT 1 FROM public.facts f WHERE f.event_id=e.id) OR NOT EXISTS(SELECT 1 FROM public.validations v WHERE v.event_id=e.id) OR EXISTS(SELECT 1 FROM public.validations v WHERE v.event_id=e.id AND v.status<>'supported') OR EXISTS(SELECT 1 FROM public.facts f LEFT JOIN public.document_chunks c ON c.id=f.chunk_id WHERE f.event_id=e.id AND (f.validation_status<>'supported' OR c.id IS NULL OR c.document_id<>e.document_id OR length(trim(f.quote))=0 OR position(f.quote IN c.text)=0))) AND NOT EXISTS(SELECT 1 FROM ancestors a JOIN public.changes c ON c.event_id=a.id JOIN public.facts f ON f.id=c.previous_fact_id JOIN public.events old ON old.id=f.event_id JOIN public.events cur ON cur.id=c.event_id WHERE old.published_at>=cur.published_at OR old.company_id<>cur.company_id) $$;
REVOKE ALL ON FUNCTION app_private.sb_event_visible(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION app_private.sb_event_visible(text) TO authenticated;
CREATE OR REPLACE FUNCTION app_private.sb_immutable_evidence() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN IF TG_TABLE_NAME='documents' THEN IF (to_jsonb(OLD)-'state') IS DISTINCT FROM (to_jsonb(NEW)-'state') THEN RAISE EXCEPTION 'immutable_source_create_new_revision'; END IF; ELSIF to_jsonb(OLD) IS DISTINCT FROM to_jsonb(NEW) THEN RAISE EXCEPTION 'immutable_evidence_create_new_revision'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS sb_immutable_document ON public.documents; CREATE TRIGGER sb_immutable_document BEFORE UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION app_private.sb_immutable_evidence();
DROP TRIGGER IF EXISTS sb_immutable_chunk ON public.document_chunks; CREATE TRIGGER sb_immutable_chunk BEFORE UPDATE ON public.document_chunks FOR EACH ROW EXECUTE FUNCTION app_private.sb_immutable_evidence();
DROP TRIGGER IF EXISTS sb_immutable_fact ON public.facts; CREATE TRIGGER sb_immutable_fact BEFORE UPDATE ON public.facts FOR EACH ROW EXECUTE FUNCTION app_private.sb_immutable_evidence();
CREATE OR REPLACE FUNCTION public.sb_calendar_subscription_feed(token text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ DECLARE u text; r jsonb; BEGIN IF token IS NULL OR token !~ '^[a-f0-9]{64}$' THEN RETURN NULL; END IF; SELECT s.user_id INTO u FROM app_private.calendar_subscriptions s WHERE s.token_hash=encode(sha256(convert_to(token,'UTF8')),'hex') AND s.expires_at>now(); IF u IS NULL THEN RETURN NULL; END IF; SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.occurs_on),'[]'::jsonb) INTO r FROM (SELECT c.id,c.title,c.occurs_on,c.origin FROM public.calendar_items c WHERE (c.user_id=u AND c.origin='user') OR (c.origin='official' AND app_private.sb_event_visible(c.event_id) AND (EXISTS(SELECT 1 FROM public.watchlist_items i JOIN public.watchlists w ON w.id=i.watchlist_id WHERE w.user_id=u AND i.company_id=c.company_id) OR EXISTS(SELECT 1 FROM public.positions p JOIN public.portfolios f ON f.id=p.portfolio_id WHERE f.user_id=u AND p.company_id=c.company_id))) ORDER BY c.occurs_on LIMIT 500) x; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.sb_calendar_subscription_feed(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.sb_calendar_subscription_feed(text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.sb_admin_action(kind text,p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u text:=(SELECT auth.uid())::text; eid text:=p->>'id'; reason text:=trim(coalesce(p->>'reason','')); e public.events%rowtype; jid text; dkey text; payload jsonb; BEGIN IF NOT app_private.sb_is_admin() THEN RAISE EXCEPTION 'admin_required' USING ERRCODE='PT403'; END IF; PERFORM public.sb_rate_limit(); IF p IS NULL OR jsonb_typeof(p)<>'object' OR octet_length(p::text)>8192 THEN RAISE EXCEPTION 'invalid_body' USING ERRCODE='PT422'; END IF; IF length(reason) NOT BETWEEN 5 AND 500 THEN RAISE EXCEPTION 'reason_min_5_characters' USING ERRCODE='PT422'; END IF; IF kind IN ('approve','reject','mark_duplicate','rerun') THEN SELECT * INTO e FROM public.events WHERE id=eid FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'event_not_found' USING ERRCODE='PT404'; END IF; END IF; CASE kind WHEN 'approve' THEN IF e.state='published' THEN RETURN jsonb_build_object('event_id',eid,'state','published'); END IF; IF e.state NOT IN ('needs_review','superseded') OR NOT EXISTS(SELECT 1 FROM public.ai_runs WHERE id=e.run_id AND status='validated') OR NOT EXISTS(SELECT 1 FROM public.facts WHERE event_id=eid) OR NOT EXISTS(SELECT 1 FROM public.validations WHERE event_id=eid) OR EXISTS(SELECT 1 FROM public.validations WHERE event_id=eid AND status<>'supported') OR EXISTS(SELECT 1 FROM public.facts f LEFT JOIN public.document_chunks c ON c.id=f.chunk_id WHERE f.event_id=eid AND (f.validation_status<>'supported' OR c.document_id IS DISTINCT FROM e.document_id OR length(trim(f.quote))=0 OR position(f.quote IN c.text)=0)) OR EXISTS(SELECT 1 FROM public.changes c JOIN public.facts f ON f.id=c.previous_fact_id JOIN public.events old ON old.id=f.event_id WHERE c.event_id=eid AND (NOT app_private.sb_event_visible(old.id) OR old.published_at>=e.published_at OR old.company_id<>e.company_id)) OR NOT EXISTS(SELECT 1 FROM public.briefs WHERE event_id=eid) THEN RAISE EXCEPTION 'publication_blocked_by_evidence_validation' USING ERRCODE='PT409'; END IF; UPDATE public.events SET state='superseded' WHERE document_id=e.document_id AND id<>eid AND state='published'; UPDATE public.events SET state='published',published_to_users_at=now() WHERE id=eid; WHEN 'reject' THEN UPDATE public.events SET state='rejected' WHERE id=eid; WHEN 'mark_duplicate' THEN IF NOT EXISTS(SELECT 1 FROM public.events WHERE id=p->>'duplicate_of' AND id<>eid AND company_id=e.company_id AND state='published') THEN RAISE EXCEPTION 'published_same_company_target_required' USING ERRCODE='PT422'; END IF; UPDATE public.events SET state='duplicate',duplicate_of=p->>'duplicate_of' WHERE id=eid; WHEN 'rerun' THEN jid:=gen_random_uuid()::text; payload:=jsonb_build_object('document_id',e.document_id,'revision','pipeline-v1-review-'||jid); INSERT INTO public.jobs(id,kind,dedupe_key,payload,state,attempts,max_attempts,available_at,created_at) VALUES(jid,'parse','parse:'||e.document_id||':'||jid,payload::json,'queued',0,5,now(),now()); WHEN 'retry_job' THEN UPDATE public.jobs SET state='queued',attempts=0,available_at=now(),lease_until=NULL,lease_token=NULL,finished_at=NULL WHERE id=eid AND state IN ('dead','retry'); IF NOT FOUND THEN RAISE EXCEPTION 'failed_job_required' USING ERRCODE='PT409'; END IF; WHEN 'resolve_report' THEN UPDATE public.feedback SET state='resolved' WHERE id=eid; IF NOT FOUND THEN RAISE EXCEPTION 'report_not_found' USING ERRCODE='PT404'; END IF; WHEN 'ingest' THEN IF NOT EXISTS(SELECT 1 FROM public.companies WHERE id=eid AND NOT is_demo) THEN RAISE EXCEPTION 'live_company_required' USING ERRCODE='PT422'; END IF; jid:=gen_random_uuid()::text; dkey:='manual-company:'||eid||':'||to_char(now(),'YYYYMMDDHH24'); payload:=jsonb_build_object('company_id',eid,'since',(current_date-7)::text,'until',current_date::text); INSERT INTO public.jobs(id,kind,dedupe_key,payload,state,attempts,max_attempts,available_at,created_at) VALUES(jid,'ingest_company',dkey,payload::json,'queued',0,5,now(),now()) ON CONFLICT(dedupe_key) DO NOTHING; SELECT id INTO jid FROM public.jobs WHERE dedupe_key=dkey; ELSE RAISE EXCEPTION 'unknown_admin_action' USING ERRCODE='PT404'; END CASE; INSERT INTO public.audit_logs(id,actor_id,action,target_id,details,created_at) VALUES(gen_random_uuid()::text,u,kind,eid,jsonb_build_object('reason',reason,'job_id',jid)::json,now()); RETURN jsonb_build_object('id',eid,'job_id',jid,'state',(SELECT state FROM public.events WHERE id=eid)); END $$;
REVOKE ALL ON FUNCTION public.sb_admin_action(text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sb_admin_action(text,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION app_private.sb_notify_on_publish() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a record; relevance float; novelty float; source_quality float; rank_score float; BEGIN IF NEW.state<>'published' OR OLD.published_to_users_at IS NOT NULL THEN RETURN NEW; END IF; novelty:=CASE WHEN EXISTS(SELECT 1 FROM public.changes WHERE event_id=NEW.id AND change_type IN ('increased','decreased','wording_changed')) THEN 1 ELSE 0.3 END; SELECT CASE WHEN provider IN ('dart','sec') THEN 1 ELSE 0.5 END INTO source_quality FROM public.documents WHERE id=NEW.document_id; FOR a IN SELECT * FROM public.alerts WHERE enabled AND created_at<=NEW.published_to_users_at LOOP relevance:=0; IF EXISTS(SELECT 1 FROM public.positions p JOIN public.portfolios f ON f.id=p.portfolio_id WHERE f.user_id=a.user_id AND p.company_id=NEW.company_id) THEN relevance:=1; ELSIF EXISTS(SELECT 1 FROM public.watchlist_items i JOIN public.watchlists w ON w.id=i.watchlist_id WHERE w.user_id=a.user_id AND i.company_id=NEW.company_id) THEN relevance:=0.6; END IF; rank_score:=(0.3*relevance+0.2*greatest(0,least(1,NEW.materiality))+0.15*novelty+0.15*source_quality+0.1*exp(-ln(2)*greatest(0,extract(epoch FROM(now()-NEW.published_at))/3600)/48))/0.9; IF relevance>0 AND rank_score>=a.min_score AND (json_array_length(a.event_types)=0 OR a.event_types::jsonb ? NEW.event_type) THEN INSERT INTO public.notifications(id,user_id,alert_id,event_id,created_at) VALUES(gen_random_uuid()::text,a.user_id,a.id,NEW.id,now()) ON CONFLICT(alert_id,event_id) DO NOTHING; END IF; END LOOP; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS sb_notify_publish ON public.events; CREATE TRIGGER sb_notify_publish AFTER UPDATE OF state ON public.events FOR EACH ROW EXECUTE FUNCTION app_private.sb_notify_on_publish();
CREATE OR REPLACE FUNCTION public.sb_health() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT jsonb_build_object('database_ready',to_regclass('public.users') IS NOT NULL AND to_regprocedure('public.sb_user_action(text,jsonb)') IS NOT NULL,'schema','signalbrief-hosted-release-1') $$;
REVOKE ALL ON FUNCTION public.sb_health() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.sb_health() TO anon,authenticated;
NOTIFY pgrst,'reload schema';